'use strict';

// MODULES //

var acosh = require( '@stdlib/math/base/special/acosh' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Computes the hyperbolic arcsecant of a single-precision floating-point number.
*
* ## Method
*
* ```tex
* \operatorname{asechf}(x) = \operatorname{acosh}(\frac{1}{x})
* ```
*
* @param {number} x - input value
* @returns {number} hyperbolic arcsecant
*
* @example
* var v = asechf( 1.0 );
* // returns 0.0
*
* @example
* var v = asechf( 0.5 );
* // returns ~1.317
*
* @example
* var v = asechf( NaN );
* // returns NaN
*/
function asechf( x ) {
	return float64ToFloat32( acosh( 1.0 / float64ToFloat32( x ) ) );
}


// EXPORTS //

module.exports = asechf;
